BASE='"cap":12,"after":0,"toStance":true,"plant":true,"plantWatch":true,"plantAnkle":0.7,"tuckSit":true,"sitPose":false,"sitFoot":0,"sitShin":0.4,"sitHand":0.05,"sitToward":0.15,"sitResponse":0.6,"sitDoneKnee":2.5,"sitPosture":{"hip.@ flexion":0.7,"ankle.@ dorsiflexion":0.3},"watch":true,"watchByHeight":true,"stopAfter":"rise","watchPosture":{"shoulder.@ flexion":0.2,"elbow.@ flexion":0.4},"watchRate":1.6'
run() { echo "== $1"; node sitback.mjs --variant dorsi0.8+toe0.06 --options "{$BASE,$2}" 2>&1 | grep seed | node -e 'let a=require("fs").readFileSync(0,"utf8").trim().split("\n").map(JSON.parse);for(const r of a)console.log(r.seed,r.steps.join(" "),"| paused",JSON.stringify(r.pausedInRise),"ball",r.highestBallInRiseCm,"| stood",r.verified,r.fell?"FELL":"",r.ended!=="handed back"?r.ended:"");const v=a.map(r=>r.verified??99).sort((x,y)=>x-y);console.log("median",((v[1]+v[2])/2).toFixed(2),"worst",v[3])'; }
NOW='"sitHold":0.05,"watchEnd":0.85,"watchStill":0.3,"watchHold":0.05,"watchDone":0.5,"watchEach":-1,"plantHipGain":20,"watchLift":0.03,"watchGraded":0.015'
sweep() { echo "== $1"; node sitback.mjs --variant ${VARIANT:-dorsi0.8+toe0.06} --held ${HELD:-empty} --seeds ${3:-1-16} --options "{$BASE,$NOW${2:+,$2}}" 2>&1 | grep seed | node -e 'let a=require("fs").readFileSync(0,"utf8").trim().split("\n").map(JSON.parse);const v=a.map(r=>r.verified??99).sort((x,y)=>x-y),n=v.length;const st=a.map(r=>r.stillBeforeStance);const climb=a.map(r=>r.climbAt??99).sort((x,y)=>x-y);console.log("stood: median",((v[(n-1)>>1]+v[n>>1])/2).toFixed(2),"worst",v[n-1],"within 6 s",v.filter(x=>x<=6).length+"/"+n,"| stance takes over: median",((climb[(n-1)>>1]+climb[n>>1])/2).toFixed(2),"| still",(st.reduce((a,b)=>a+b,0)/n).toFixed(2),"rise slowed",(a.reduce((x,r)=>x+(r.riseSlowed??0),0)/n).toFixed(2),"| highest ball",Math.max(...a.map(r=>r.highestBallInRiseCm??0)),"| after handover: feet down",(a.reduce((x,r)=>x+(r.afterHandover?.feetDown??0),0)/n).toFixed(2),"still enough",(a.reduce((x,r)=>x+(r.afterHandover?.stillEnough??0),0)/n).toFixed(2),"| feet apart standing: median",(()=>{const f=a.map(r=>r.feetApartStanding??0).sort((x,y)=>x-y);return ((f[(n-1)>>1]+f[n>>1])/2).toFixed(2)})(),"widest",Math.max(...a.map(r=>r.feetApartStanding??0)),"| fails",a.filter(r=>r.verified==null).map(r=>r.seed+": "+(r.ended??"")).join("; ").slice(0,300))'; }
